    'faq_q2' => '<strong>Is it a CRM au a kazi manager?</strong><br>Both. A CRM for clients na counterparties, a kazi manager for kazi, plus mradi management, chat, kalenda, na AI.',
    'faq_q3' => '<strong>Is it suitable for freelancers?</strong><br>Yes. There is no minimum timu size. A single mtumiaji gets CRM, kazi, an AI day plan, na chat without per-seat fees.',
    'faq_q4' => '<strong>Does it kazi on shared hosting?</strong><br>Yes. PHP 8.1+ na MySQL are enough.  browser installer configures everything.',
    'faq_q5' => '<strong>Are there limits on watumiaji na kazi?</strong><br>No. Unlimited watumiaji, kazi, miradi, na clients.  only limitation is server capacity.',
    'faq_q6' => '<strong>Where is  data stored?</strong><br>100% on your server.  system never syncs data to  cloud.',
    'faq_q7' => '<strong>What AI tools are inapatikana?</strong><br>20+ tools: idea exploration, day/week plans, summaries, checklists, risks, meeting preparation.',
    'faq_q8' => '<strong>Is there an API?</strong><br>Yes, a REST API with an OpenAPI 3.1 spec generated from code.',
